	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void innerJoinOperatorRetainsBothFiniteInputInventories(boolean reverse, @TempDir File directory) {
		BindingSetAssignment kinds = kinds();
		StatementPattern code = code();
		Join inner = reverse ? new Join(code, kinds) : new Join(kinds, code);
		Join root = new Join(inner, outer());
		var call = PackedCostTestSupport.binaryOperator(PlanningGraphDomain.defaultGraph(), root);
		int kindId = call.query().childRelationId(call.leftRelationId(), reverse ? 1 : 0);
		int codeId = call.query().childRelationId(call.leftRelationId(), reverse ? 0 : 1);
		withSession(directory, root, call, session -> {
			var kind = leaf(session, call, kindId);
			var codeLeaf = leaf(session, call, codeId);
			var outer = leaf(session, call, call.rightRelationId());
			PackedCostEstimate finite = finiteCode(session, call, kindId, codeId, kind);
			assertParentRows(session, call, finite, outer, 15.0d,
					"the complete append-factor state reconstructs all five code matches");
			session.refineOperator(call.leftRelationId(), call.operatorContext(
					reverse ? codeLeaf.outputRows() : kind.outputRows(),
					reverse ? kind.outputRows() : codeLeaf.outputRows(),
					reverse ? codeLeaf.evidenceStateId() : kind.evidenceStateId(),
					reverse ? kind.evidenceStateId() : codeLeaf.evidenceStateId()), finite);
			assertEquals(5.0d, finite.outputRows(), 0.0d);
			assertParentRows(session, call, finite, outer, 15.0d,
					"refining the identical binary operator must retain both statistical inputs");
		});
	}

