	private static PackedCostEstimate controlledLeaf(PackedCostSession session,
			PackedCostTestSupport.BinaryCostCall call, int relationId, double rows) {
		var output = new PackedCostEstimate();
		output.setRows(rows, rows);
		session.estimateLeaf(relationId, call.emptyContext(), output);
		return output;
	}

	private static PackedCostEstimate leaf(PackedCostSession session,
			PackedCostTestSupport.BinaryCostCall call, int relation) {
		var output = new PackedCostEstimate();
		session.estimateLeaf(relation, call.emptyContext(), output);
		return output;
	}

	private static PackedCostEstimate finiteCode(PackedCostSession session,
			PackedCostTestSupport.BinaryCostCall call, int kindId, int codeId, PackedCostEstimate kinds) {
		var finite = new PackedCostEstimate();
		session.appendFactor(codeId, PackedCostTestSupport.prefixContext(new int[] { kindId }, 1,
				kinds.outputRows(), kinds.evidenceStateId()), finite);
		assertEquals(5.0d, finite.outputRows(), 0.0d);
		assertEquals(
				"frontier-v2-omni-finite-domain+frontier-v2-exact-projected-distinct-conditional-bounded-uncertainty-selection",
				finite.estimateSource());
		assertEquals("frontier_v2_omni_finite_domain", finite.estimateFusion());
		assertTrue(finite.evidenceStateId() > 0);
		return finite;
	}

	private static void assertParentRows(PackedCostSession session, PackedCostTestSupport.BinaryCostCall call,
			PackedCostEstimate left, PackedCostEstimate right, double expected, String reason) {
		var parent = new PackedCostEstimate();
		parent.setContextualRows(expected, expected);
		session.refineIntermediateJoin(call.operatorContext(left.outputRows(), right.outputRows(),
				left.evidenceStateId(), right.evidenceStateId()), parent);
		assertEquals(expected, parent.outputRows(), 0.0d,
				reason + "; source=" + parent.estimateSource() + "; fusion=" + parent.estimateFusion());
	}

	private static void withSession(File directory, TupleExpr root, PackedCostTestSupport.BinaryCostCall call,
			Consumer<PackedCostSession> check) {
		withSession(directory, root, call, check, -1L);
	}

	private static void withSession(File directory, TupleExpr root, PackedCostTestSupport.BinaryCostCall call,
			Consumer<PackedCostSession> check, long expectedRows) {
		withSession(directory, root, call, check, expectedRows, null, -1L);
	}

	private static void withSession(File directory, TupleExpr root, PackedCostTestSupport.BinaryCostCall call,
			Consumer<PackedCostSession> check, long expectedRows, String distinctName, long expectedDistinct) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc")
				.setFrontierEstimatorMode(FrontierEstimatorMode.AUTHORITATIVE));
		SailRepository repository = new SailRepository(store);
		repository.init();
		try {
			try (var connection = repository.getConnection()) {
				connection.begin();
				for (int i = 0; i < 3; i++) {
					connection.add(VF.createIRI("urn:lineage:outer:" + i), RDF.TYPE, OUTER);
				}
				for (int i = 0; i < 5; i++) {
					connection.add(VF.createIRI("urn:lineage:inner:" + i), CODE, VF.createLiteral("keep" + i % 2));
				}
				for (int i = 0; i < 3; i++) {
					connection.add(VF.createIRI("urn:lineage:noise:" + i), CODE, VF.createLiteral("drop"));
				}
				connection.commit();
			}
			assertEquals(FrontierStatisticsAvailability.READY, store.rebuildFrontierStatistics().availability());
			var backing = store.getSailStore();
			try (SailSource source = backing.getExplicitSailSource().fork();
					SailDataset dataset = source.dataset(IsolationLevels.SNAPSHOT_READ)) {
				var tripleSource = new SailDatasetTripleTermSource(backing.getValueFactory(), dataset);
				var statistics = backing.getEvaluationStatistics();
				var runtime = ((LmdbEstimatorRuntimeProvider) statistics).estimatorRuntime();
				var strategy = store.getEvaluationStrategyFactory()
						.createEvaluationStrategy(null, tripleSource, statistics);
				new LmdbQueryOptimizerPipeline(strategy, tripleSource, statistics)
						.withPreparedQueryEntry(new QueryRoot(root.clone()), null, EmptyBindingSet.getInstance(),
								(prepared, cascades) -> {
									var model = new LmdbPackedCostModel(runtime, tripleSource.getSnapshotEpoch(), true,
											tripleSource, strategy);
									try (var session = model.openSession(call.query())) {
										if (expectedRows >= 0L) {
											long actualRows = 0L;
											Set<Value> actualDistinct = new HashSet<>();
											try (var result = strategy.precompile(root.clone())
													.evaluate(EmptyBindingSet.getInstance())) {
												while (result.hasNext()) {
													BindingSet row = result.next();
													if (distinctName != null && row.getValue(distinctName) != null) {
														actualDistinct.add(row.getValue(distinctName));
													}
													actualRows++;
												}
											}
											assertEquals(expectedRows, actualRows,
													"actual public native execution authenticates the exact supplied child bag");
											if (distinctName != null) {
												assertEquals(expectedDistinct, actualDistinct.size(),
														"actual public output values authenticate the demanded distinct population");
											}
										}
										check.accept(session);
									}
									return null;
								});
			}
		} finally {
			repository.shutDown();
		}
	}

	private static BindingSetAssignment kinds() {
		var assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("kind"));
		assignment.setBindingSets(List.of(new ListBindingSet(List.of("kind"), VF.createLiteral("keep0")),
				new ListBindingSet(List.of("kind"), VF.createLiteral("keep1"))));
		return assignment;
	}

	private static StatementPattern code() {
		return new StatementPattern(Var.of("inner"), Var.of("code", CODE), Var.of("kind"));
	}

	private static StatementPattern outer() {
		return new StatementPattern(Var.of("outer"), Var.of("type", RDF.TYPE), Var.of("outerType", OUTER));
	}
